SourceCode.Declaration:
[TFMDescription("Expression to find value of a InventSum field. Takes the InventSum Record, and Field Name as Parameters")]
class MobExpressionsInventSumField extends TFMExpressions
{
}

Method.Source:
public str processExpressionCommon(Common _common, FieldName _fieldName = '')
{
    InventSum                   inventSum, inventSumOriginal;
    str                         retValue;
    ItemId                      itemId;
    InventDim                   inventDimLookup, inventDim;
    FieldName                   fieldName = _fieldName;
    InventDimParm				inventDimParm;

    if (_common.TableId != tableNum(InventSum))
    {
        return '';
    }
    inventSumOriginal   = _common;
    itemId              = inventSumOriginal.ItemId;
    inventDimLookup     = inventSumOriginal.inventDim();

    inventDimParm.initFromInventDim(inventDimLookup);

    while #InventDimSelect(inventDim,inventDimLookup,inventDimParm, forcePlaceholders TableId from,SerialIdIdx,inventDim.WMSLocationId)
        join inventSum
        index hint DimIdIdx
            /*group by inventDim.InventSiteId, inventDim.InventLocationId, inventDim.WMSLocationId, inventDim.inventBatchId, inventDim.inventSerialId,inventDim.configId, inventDim.InventColorId, inventDim.InventSizeId, inventDim.InventStyleId
                    ,inventSum.RecId, inventSum.ItemId, inventSum.InventDimId    // Since InventSum Primary key is ItemId,InventDimId  grouping by every field in InventDim is same as grouping by inventSum.RecId*/
    where InventDim.InventDimId == inventSum.InventDimId
                  && inventSum.itemId == itemId
    {
        retValue = strFmt('%1',inventSum.(fieldName2Id(inventSum.TableId, _fieldName)));
    }
    return retValue;
}
